{
    "method": {
        "argcnt": 10000,
        "cmd": "query"
    },
    "args": ["*", "capacity_description"],
    "dstype": "kbdata",
    "sqlselect": "",
    "criteria": [
        {
            "document_type": "capacity_description",
            "metadata_status": "available"
        }
    ],
    "options": {
        "strategy": "PARALLEL_AGGREGATE",
        "time_budget_ms": 2000,
        "annotate_source": true,
        "client_filters": {
            "node_types": {
                "$contains": "tosca.nodes.Compute.GPU"
            },
            "topology.edge_compute_node_01.properties.available_memory": {
                "$regex": ".*[0-9]{2,}.*GB.*"
            }
        }
    }
}

